// Finds acronyms in text and decides where to spell them out. Shared by the page plugin
// (rehype-acronyms.mjs) and the interactive components (Inline.tsx), so both behave the same.
import list from '../data/acronyms.json' with { type: 'json' };

export const ACRONYMS = Object.fromEntries(Object.entries(list).filter(([k]) => !k.startsWith('$')));

const escape = (s) => s.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
const alternation = Object.keys(ACRONYMS).sort((a, b) => b.length - a.length).map(escape).join('|');
// Whole words only (not inside other words), optional plural "s".
const PATTERN = new RegExp(`(?<![A-Za-z0-9_\\-])(${alternation})(s?)(?![A-Za-z0-9_])`, 'g');

/**
 * Splits text into plain strings and acronym parts.
 * `seen` is the set of acronyms already spelled out in this scope (a page, or a card);
 * the first use in a scope gets `expand: true` unless the text already spells it out.
 */
export function splitAcronyms(text, seen) {
  const parts = [];
  let last = 0;
  for (const m of text.matchAll(PATTERN)) {
    const [whole, short, plural] = m;
    const at = m.index;
    if (at > last) parts.push(text.slice(last, at));
    const after = text.slice(at + whole.length);
    const alreadySpelled = /^\s*\(/.test(after);
    const expand = !seen.has(short) && !alreadySpelled;
    seen.add(short);
    parts.push({ short: whole, full: ACRONYMS[short] + (plural ? 's' : ''), expand });
    last = at + whole.length;
  }
  if (last < text.length) parts.push(text.slice(last));
  return parts;
}

const html = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** HTML for Astro components: <abbr> everywhere, spelled out on first use in `seen`. */
export function acronymHtml(text, seen) {
  return splitAcronyms(text, seen)
    .map((p) => (typeof p === 'string' ? html(p) : `<abbr title="${html(p.full)}">${html(p.short)}</abbr>${p.expand ? ` (${html(p.full)})` : ''}`))
    .join('');
}

// The site's areas: one per project, plus the shared "Combined knowledge".
export type AreaId = 'road-risk' | 'project-viewer' | 'learning-app' | 'knowledge';

export const AREAS: Record<AreaId, { label: string; accent: { dark: string; light: string } }> = {
  'road-risk': { label: 'Road Risk', accent: { dark: '#f59e0b', light: '#b45309' } },
  'project-viewer': { label: 'projectViewer', accent: { dark: '#a78bfa', light: '#6d28d9' } },
  'learning-app': { label: 'This learning app', accent: { dark: '#2dd4bf', light: '#0f766e' } },
  knowledge: { label: 'Combined knowledge', accent: { dark: '#60a5fa', light: '#1d4ed8' } },
};

/** Pages under these top-level folders belong to Combined knowledge. */
const KNOWLEDGE = new Set(['knowledge', 'concepts', 'glossary', 'stack', 'journey', 'start']);

export function areaOf(id: string): AreaId | null {
  const top = id.split('/')[0];
  if (top in AREAS && top !== 'knowledge') return top as AreaId;
  return KNOWLEDGE.has(top) ? 'knowledge' : null;
}

// Build-time plugin for every Markdown/MDX page, including imported records:
// wraps acronyms in <abbr title="full form"> and spells out the first use on each page.
import { splitAcronyms } from './acronyms.mjs';

const SKIP = new Set(['code', 'pre', 'kbd', 'samp', 'abbr', 'script', 'style', 'svg', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6']);

export default function rehypeAcronyms() {
  return (tree) => {
    const seen = new Set();
    const walk = (node) => {
      if (!node.children) return;
      const out = [];
      for (const child of node.children) {
        if (child.type === 'text') {
          for (const p of splitAcronyms(child.value, seen)) {
            if (typeof p === 'string') out.push({ type: 'text', value: p });
            else {
              out.push({ type: 'element', tagName: 'abbr', properties: { title: p.full }, children: [{ type: 'text', value: p.short }] });
              if (p.expand) out.push({ type: 'text', value: ` (${p.full})` });
            }
          }
        } else {
          // Skip code, headings and embedded components (they handle acronyms themselves).
          if (!(child.type === 'element' && SKIP.has(child.tagName)) && !String(child.type).startsWith('mdxJsx')) walk(child);
          out.push(child);
        }
      }
      node.children = out;
    };
    walk(tree);
  };
}

// Shared helpers for components.

/** A link inside the site that respects the GitHub Pages base path. */
export function href(path: string): string {
  const base = import.meta.env.BASE_URL.replace(/\/$/, '');
  const clean = path.replace(/^\//, '');
  return `${base}/${clean}${clean && !clean.includes('#') && !clean.endsWith('/') ? '/' : ''}`;
}

export const PROJECT_NAMES: Record<string, string> = {
  'road-risk': 'Road Risk',
  'project-viewer': 'projectViewer',
  'learning-app': 'Learning app',
};

export const LAYER_NAMES: Record<string, string> = {
  language: 'Languages',
  data: 'Data',
  backend: 'Backend',
  frontend: 'Frontend',
  testing: 'Testing',
  quality: 'Code quality',
  workflow: 'Workflow',
  delivery: 'Delivery',
  ai: 'AI',
};

// Scoped navigation: inside a project you see only that project; the shared material lives in
// "Combined knowledge". The full sidebar is defined once in astro.config.mjs; this middleware
// keeps only the current area's group, and limits previous/next links to that area.
import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import { AREAS, areaOf } from './lib/areas';

type Entry = { type: 'link' | 'group'; label: string; href?: string; isCurrent?: boolean; entries?: Entry[] };

function flatten(entries: Entry[]): Entry[] {
  return entries.flatMap((e) => (e.type === 'group' ? flatten(e.entries ?? []) : [e]));
}

export const onRequest = defineRouteMiddleware((context) => {
  const route = context.locals.starlightRoute;
  const area = areaOf(route.id);
  if (!area) return;
  const group = (route.sidebar as Entry[]).find((e) => e.type === 'group' && e.label === AREAS[area].label);
  if (!group) return;

  const home: Entry = { type: 'link', label: 'All projects', href: `${import.meta.env.BASE_URL.replace(/\/$/, '')}/`, isCurrent: false };
  route.sidebar = [
    { ...home, badge: undefined, attrs: { class: 'lx-nav-home' } },
    ...(group.entries ?? []),
  ] as typeof route.sidebar;

  const pages = flatten(group.entries ?? []);
  const i = pages.findIndex((p) => p.isCurrent);
  route.pagination = {
    prev: i > 0 ? (pages[i - 1] as never) : undefined,
    next: i >= 0 && i < pages.length - 1 ? (pages[i + 1] as never) : undefined,
  };

  // Each area has its own accent colour, so you always know where you are.
  const { dark, light } = AREAS[area].accent;
  route.head.push({
    tag: 'style',
    attrs: {},
    content: `:root{--sl-color-accent:${dark};--lx-area:${dark}}:root[data-theme='light']{--sl-color-accent:${light};--lx-area:${light}}`,
  });
});

symbols.doc:
Splits text into plain strings and acronym parts.
`seen` is the set of acronyms already spelled out in this scope (a page, or a card);
the first use in a scope gets `expand: true` unless the text already spells it out.
